class IntelligentPrefetcher{constructor(){this.prefetchQueue=new Set,this.observer=null,this.isInitialized=!1}shouldPrefetch(){if(navigator.connection){const e=navigator.connection;if("slow-2g"===e.effectiveType||"2g"===e.effectiveType)return!1;if(e.saveData)return!1}if(navigator.deviceMemory&&navigator.deviceMemory<=2)return!1;/iPad|iPhone|iPod/.test(navigator.userAgent);return!0}prefetchUrl(e){this.prefetchQueue.has(e)||(this.prefetchQueue.add(e),fetch(e,{priority:"low",headers:{"X-Prefetch":"true",Purpose:"prefetch"}}).then(e=>{}).catch(e=>{}).finally(()=>{this.prefetchQueue.delete(e)}))}initializeObserver(){this.shouldPrefetch()&&(this.observer=new IntersectionObserver(e=>{e.forEach(e=>{if(e.isIntersecting){const t=e.target,r=t.href||t.dataset.href;r&&!this.prefetchQueue.has(r)&&(this.prefetchUrl(r),this.observer.unobserve(t))}})},{rootMargin:"50px"}),this.isInitialized=!0)}observeLinks(e){this.isInitialized||this.initializeObserver();document.querySelectorAll(e).forEach(e=>{this.observer&&this.observer.observe(e)})}prefetchMainPages(){if(!this.shouldPrefetch())return;const e=["/formations/html5","/formations/css3","/formations/javascript","/formations/php","/formations/laravel"];(window.requestIdleCallback||function(e){const t=Date.now();return setTimeout(()=>{e({didTimeout:!1,timeRemaining:()=>Math.max(0,50-(Date.now()-t))})},1)})(()=>{e.forEach((e,t)=>{setTimeout(()=>{this.prefetchUrl(window.location.origin+e)},200*t)})})}}const prefetcher=new IntelligentPrefetcher;document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{prefetcher.observeLinks(".tech-link-carousel"),prefetcher.observeLinks(".formation-card a"),prefetcher.observeLinks(".featured-article-link"),prefetcher.prefetchMainPages()},2e3)}),window.IntelligentPrefetcher=IntelligentPrefetcher,window.prefetcher=prefetcher;